INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40611, 'Exodus 38:21', 'Exodus', 38, 21, 'دا هغه لست دی چې د فلزاتو هغه اندازه په کې ده چې په سپېڅلې خېمه کې په هغه ځای کې ورڅخه کار واخیستل شو چې د تیږو دوه لوحې چې لس حکمونه ورباندې لیکل شوي وو، ساتل شوې وې. د لست فرمایش موسی ورکړی ؤ او هغو لاویانو جوړ کړ چې د هارون کاهن د زوی ایتامار تر لارښوونې لاندې یې کار کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_21.mp3', '', 1761754199, 1761754199),
(40612, 'Exodus 38:22', 'Exodus', 38, 22, 'د یهودا د قبیلې بزل ییل د اوري زوی او د حور لمسي هغه ټول شیان جوړ کړل چې د هغو د جوړولو حکم څښتن په موسی باندې کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_22.mp3', '', 1761754199, 1761754199),
(40613, 'Exodus 38:23', 'Exodus', 38, 23, 'د هغه سره د دان د قبیلې د اخیسامک زوی اهولیاب ؤ، هغه یو کسبګر او طرح کوونکی ؤ او د ابي، بانجاني او سرو وړیو او د ښه کتان ګلدوز هم ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_23.mp3', '', 1761754199, 1761754199),
(40614, 'Exodus 38:24', 'Exodus', 38, 24, 'د هغو ټولو سرو زرو وزن چې خلکو څښتن ته وقف کړي وو او د سپېڅلي ځای په کار کې ورڅخه کار واخیستل شو، زر کیلو ګرامه ؤ. دا د هغه وزن له مخې وو چې په سپېڅلي ځای کې ورڅخه کار اخیستل کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_24.mp3', '', 1761754199, 1761754199),
(40615, 'Exodus 38:25', 'Exodus', 38, 25, 'د هغو سپینو زرو اندازه چې د اسراییلو د قوم د هغو خلکو څخه تر لاسه شول چې په سرشمېرنه کې شمېرل شوي وو، ۳۴۲۵ کیلو ګرامه وه، د هغه وزن له مخې چې په سپېڅلي ځای کې ورڅخه کار اخیستل کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_25.mp3', '', 1761754199, 1761754199),
(40616, 'Exodus 38:26', 'Exodus', 38, 26, 'د کس په سر یو مثقال راتله، (دا مثقال د سپېڅلي ځای د مثقال له مخې ؤ)، ټول خلک چې شمېرل شوي وو او عمر یې د شلو کالو څخه زیات ؤ، ټول ۶۰۳۵۵۰ تنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_26.mp3', '', 1761754199, 1761754199),
(40617, 'Exodus 38:27', 'Exodus', 38, 27, 'د سپینو زرو څخه ۳۴۰۰ کیلو ګرامه د دې دپاره وکارول شول چې د سپېڅلي ځای او پردې دپاره سل پایې جوړې شي او د هرې پایې دپاره څلوردېرش کیلو ګرامه کارول شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_27.mp3', '', 1761754199, 1761754199),
(40618, 'Exodus 38:28', 'Exodus', 38, 28, 'د پاتې پنځه ویشتو کیلو ګرامو سپینو زرو څخه بزل ییل سیخونه، د ستنو دپاره چنګکونه او د هغو د سرونو دپاره پوښونه جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_28.mp3', '', 1761754199, 1761754199),
(40619, 'Exodus 38:29', 'Exodus', 38, 29, 'د هغو برنجو اندازه چې خلکو څښتن ته وقف کړي وو، ۲۴۰۰ کیلو ګرامه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_29.mp3', '', 1761754199, 1761754199),
(40620, 'Exodus 38:30', 'Exodus', 38, 30, 'هغه له دې برنجو څخه د لاندېنیو شیانو په جوړولو کې کار واخیست: د سپېڅلې خېمې د دروازې دپاره پایې، د قربانۍ برنجي ځای او د هغې جالۍ او ټول لوښي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_30.mp3', '', 1761754199, 1761754199),
(40621, 'Exodus 38:31', 'Exodus', 38, 31, 'د ګردچاپېره حوېلۍ او د هغې د دروازې دپاره پایې او د خېمې او ګردچاپېره حوېلۍ دپاره ټول موږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus38_verse_31.mp3', '', 1761754199, 1761754199),
(40622, 'Psalms 31:1', 'Psalms', 31, 1, 'ما پناه راوړې تاته ای څښتنه! مه پرېږده مې ته هېڅکله خجالت ته ته عادل یې ماته راکړه نجات', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_1.mp3', '', 1761754199, 1761754199),
(40623, 'Psalms 31:2', 'Psalms', 31, 2, 'ونیسه غوږ ماته واوره زما دعا زر شه ماته نجات راکړه زما دپاره پناه ځای شه چې ساتنه زما وکړې ته زما قوي کلا شه چې نجات راته راکړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_2.mp3', '', 1761754199, 1761754199),
(40624, 'Psalms 31:3', 'Psalms', 31, 3, 'زما کلا او پناه ځای یې ته ته د خپل نوم په خاطر وکړه هدایت او لارښوونه راته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_3.mp3', '', 1761754199, 1761754199),
(40625, 'Psalms 31:4', 'Psalms', 31, 4, 'ما له هغه دامه وساته چې دوی دی راته ایښی ځکه ته مې پناه ځای یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_4.mp3', '', 1761754199, 1761754199),
(40626, 'Psalms 31:5', 'Psalms', 31, 5, 'زه خپل روح سپارمه تاته ما به وژغورې څښتنه وفادار یې ته ای خدایه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_5.mp3', '', 1761754199, 1761754199),
(40627, 'Psalms 31:6', 'Psalms', 31, 6, 'له هغو خلکو څخه کرکه کوم چې عبادت کړي د بتانو بې‌ارزښتو خو زه په تا باندې توکل کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_6.mp3', '', 1761754199, 1761754199),
(40628, 'Psalms 31:7', 'Psalms', 31, 7, 'زه به خوشحاله یم خوښي به کوم ستا په تلپاتې مینه ځکه چې تا زما درد ولیدلو او د تکلیف نه مې خبر شولې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_7.mp3', '', 1761754199, 1761754199),
(40629, 'Psalms 31:8', 'Psalms', 31, 8, 'زه دې ورنه کړم په لاس د دښمنانو خوندي ځای ته دې زه بوتلم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_8.mp3', '', 1761754199, 1761754199),
(40630, 'Psalms 31:9', 'Psalms', 31, 9, 'رحم وکړه په ما باندې ای څښتنه ځکه یمه په تکلیف کې زما سترګې ستړې شوې له ژړا نه زه بیخي یمه ستومانه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_9.mp3', '', 1761754199, 1761754199),
(40631, 'Psalms 31:10', 'Psalms', 31, 10, 'ژوند مې شو په غم تالا د خفګان د لاسه عمر مې لنډ شوی زه مې خپلو ګناهونو کړم کمزوری ان هډوکي مې له کاره دي وتلي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_10.mp3', '', 1761754199, 1761754199),
(40632, 'Psalms 31:11', 'Psalms', 31, 11, 'راته په سپکه سترګه ګوري دښمنان ټول زما په تېره بیا ګاونډیان هغوی چې پېژني ما زړه یې چوي زما څخه کله چې دوی مې په کوڅه کې ویني دوی کاندي تېښته زما څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_11.mp3', '', 1761754199, 1761754199),
(40633, 'Psalms 31:12', 'Psalms', 31, 12, 'زه هرچا یمه هېر کړی لکه مړی چې څوک هېر کړي زه په شان یم د کودي چې وي چا لېرې غورځولی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_12.mp3', '', 1761754199, 1761754199),
(40634, 'Psalms 31:13', 'Psalms', 31, 13, 'کړي ګونګوسي راپسې ډېر دښمنان اورم یې زه له هرې خوا راباندې وېره ډېره دوی پلانونه زما په ضد جوړوي هم جوړوي مې د مرګي دسیسې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_13.mp3', '', 1761754199, 1761754199),
(40635, 'Psalms 31:14', 'Psalms', 31, 14, 'خو توکل زما په تا دی ای څښتنه زه دا وایم: «ته مې خدای یې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_14.mp3', '', 1761754199, 1761754199),
(40636, 'Psalms 31:15', 'Psalms', 31, 15, 'زما ژوند دی ستا په لاس کې د دښمنانو د لاسونو نه مې خلاص کړه او له هغو نه مې خلاص کړه چې په ما پسې دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_15.mp3', '', 1761754199, 1761754199),
(40637, 'Psalms 31:16', 'Psalms', 31, 16, 'په ورین تندي وګوره خپل خدمتګار ته وژغوره ما ته په خپلې تلپاتې مینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_16.mp3', '', 1761754199, 1761754199),
(40638, 'Psalms 31:17', 'Psalms', 31, 17, 'ته مې مه پرېږده څښتنه چې خجل شم ځکه تاته زه فریاد کړم بدکاران دې خجالت شي پټه خوله دې دوی شي ښکته خپلو قبرو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_17.mp3', '', 1761754199, 1761754199),
(40639, 'Psalms 31:18', 'Psalms', 31, 18, 'د هغوی دروغجنې ژبې دې شي غلې چې مغرور او کبرجن دي چې نېکانو پسې کړي سپکې خبرې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_18.mp3', '', 1761754199, 1761754199),
(40640, 'Psalms 31:19', 'Psalms', 31, 19, 'څه عجیبه دا ښه شیان دي چې تا ساتلي دي هغوی ته چې کړي وېره له تا هر یو پوهیږي چې ته څومره نېک یې څنګه ته ساتې هغوی چې غواړي پناه ستا نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_19.mp3', '', 1761754199, 1761754199),
(40641, 'Psalms 31:20', 'Psalms', 31, 20, 'ته هغوی د نورو خلکو دسیسو نه خپل حضور کې خوندي ساتې دوی د خپلو دښمنانو له تورونو په ډاډمنه پناه ځای کې پټ ساتې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_20.mp3', '', 1761754199, 1761754199),
(40642, 'Psalms 31:21', 'Psalms', 31, 21, 'ثنا او صفت دې وي څښتن ته! کله چې زه په کلا بند ښار کې ګېر شوی ومه څه عجیبه مینه یې وکړه له ما سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_21.mp3', '', 1761754199, 1761754199),
(40643, 'Psalms 31:22', 'Psalms', 31, 22, 'زه وېرېدلی وم او خیال مې کاوه چې ستا حضور ځینې زه لېرې شړل شوی یمه خو کله ما چې زارۍ وکړې د کومک دپاره نو تا زما دعا قبوله کړله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_22.mp3', '', 1761754199, 1761754199),
(40644, 'Psalms 31:23', 'Psalms', 31, 23, 'ای خپل څښتن ته وفادارو خلکو ده سره مینه وکړئ څښتن ساتنه کوي د وفادارو خلکو خو کبرجنو ته د خپل عمل پوره سزا ورکوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_23.mp3', '', 1761754199, 1761754199),
(40645, 'Psalms 31:24', 'Psalms', 31, 24, 'اوسئ ځواکمن او زړور ای خلکو ټول هغه چې هیله له څښتن لرئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms31_verse_24.mp3', '', 1761754199, 1761754199),
(40646, 'Deuteronomy 13:1', 'Deuteronomy', 13, 1, 'فرض کړئ ستاسو په منځ کې یو نبي یا یو څوک راپیدا شي چې خوبونه تعبیروي او تاسو ته د کومې معجزې یا کوم عجیبه کار په اړه پېشګویي وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_1.mp3', '', 1761754199, 1761754199),
(40647, 'Deuteronomy 13:2', 'Deuteronomy', 13, 2, 'که چېرې هغه نښه یا هغه عجیبه کار چې د هغه په اړه یې خبرې کړې وي، رښتیا شي او هغه ووایي: ‹راځئ چې د نورو خدایانو څخه پیروي او عبادت وکړو، هغه خدایان چې مخکې مو د هغو عبادت نه دی کړی›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_2.mp3', '', 1761754199, 1761754199),
(40648, 'Deuteronomy 13:3', 'Deuteronomy', 13, 3, 'نو تاسو باید د هغه نبي یا د خوب تعبیروونکي خبرو ته غوږ ونه نیسئ. ستاسو څښتن خدای په تاسو باندې د دې دپاره ازمېښت کوي چې دا معلومه کړي چې د هغه سره د زړه له کومي مینه کوئ او که نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_3.mp3', '', 1761754199, 1761754199),
(40649, 'Deuteronomy 13:4', 'Deuteronomy', 13, 4, 'د څښتن څخه پیروي کوئ او د هغه څخه وېره کوئ. د هغه د امرونو څخه اطاعت کوئ، عبادت یې کوئ او ورته وفادار اوسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_4.mp3', '', 1761754199, 1761754199),
(40650, 'Deuteronomy 13:5', 'Deuteronomy', 13, 5, 'خو هغه خوب تعبیروونکی یا نبي ووژنئ چې تاسو ته وایي چې د څښتن یعنې هغه چا په وړاندې سرکښي وکړئ چې تاسو یې د مصر څخه چې په کې غلامان وئ، ازاد کړئ. داسې خلک بدکاره دي او هڅه کوي چې تاسو د هغې لارې څخه واړوي چې څښتن یې تاسو ته د پیروۍ کولو حکم کړی دی. د دې دپاره چې تاسو خپل ځانونه د دې بدکارۍ څخه خلاص کړئ، نو هغوی باید ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_5.mp3', '', 1761754199, 1761754199),
(40651, 'Deuteronomy 13:6', 'Deuteronomy', 13, 6, 'حتی کېدای شي چې خپل ورور یا خپل زوی یا خپله لور یا ښځه چې تاسو ورسره مینه کوئ یا خپل تر ټولو نژدې ملګری په پټه تاسو دې ته وهڅوي چې د نورو خدایانو عبادت وکړئ، یعنې د هغو خدایانو چې تاسو او ستاسو نیکونو یې هېڅکله عبادت نه دی کړی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_6.mp3', '', 1761754199, 1761754199),
(40652, 'Deuteronomy 13:7', 'Deuteronomy', 13, 7, 'کېدای شي چې د هغوی څخه کوم یو تاسو دې ته وهڅوي چې د هغو خلکو د خدایانو عبادت وکړئ چې ستاسو سره نژدې اوسیږي یا د هغو خلکو چې ستاسو څخه لېرې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_7.mp3', '', 1761754199, 1761754199),
(40653, 'Deuteronomy 13:8', 'Deuteronomy', 13, 8, 'خو هغه مه پرېږدئ چې تاسو وهڅوي، حتی غوږ هم ورته مه نیسئ. په هغه باندې رحم مه کوئ یا زړه ورباندې مه سوځوئ او د هغه راز پټ مه ساتئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_8.mp3', '', 1761754199, 1761754199),
(40654, 'Deuteronomy 13:9', 'Deuteronomy', 13, 9, 'هغه ووژنئ! لومړی یې تاسو سنګسار کړئ او بیا نور ټول خلک پرېږدئ چې سنګسار یې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_9.mp3', '', 1761754199, 1761754199),
(40655, 'Deuteronomy 13:10', 'Deuteronomy', 13, 10, 'هغه سنګسار کړئ چې مړ شي! ځکه چې د دې هڅه یې کړې ده چې تاسو د خپل څښتن خدای څخه چې تاسو یې د مصر څخه چې په کې غلامان وئ ازاد کړئ، واړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_10.mp3', '', 1761754199, 1761754199),
(40656, 'Deuteronomy 13:11', 'Deuteronomy', 13, 11, 'نو د اسراییلو ټول قوم به د دې پېښې څخه خبر شي، نو هغوی به ووېریږي او بیا به هېڅوک داسې بد کار ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_11.mp3', '', 1761754199, 1761754199),
(40657, 'Deuteronomy 13:12', 'Deuteronomy', 13, 12, 'کله چې تاسو په هغو ښارونو کې واوسېږئ چې ستاسو څښتن خدای یې درکوي، کېدای شي تاسو واورئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_12.mp3', '', 1761754199, 1761754199),
(40658, 'Deuteronomy 13:13', 'Deuteronomy', 13, 13, 'چې ستاسو د قوم ځینې بدکاره خلکو د خپل ښار خلک بې لارې کړي دي چې د داسې خدایانو عبادت وکړي چې مخکې تاسو هېڅکله د هغو عبادت نه وي کړی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_13.mp3', '', 1761754199, 1761754199),
(40659, 'Deuteronomy 13:14', 'Deuteronomy', 13, 14, 'که چېرې تاسو داسې اوازې واورئ، د هغو په هکله پوره څېړنه وکړئ او که چېرې هغه رښتیا وي او داسې د کرکې وړ پېښه شوې وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_14.mp3', '', 1761754199, 1761754199),
(40660, 'Deuteronomy 13:15', 'Deuteronomy', 13, 15, 'بیا د هغه ښار ټول خلک او د هغوی ټول حیوانات هم ووژنئ او هغه ښار په پوره توګه وران کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_15.mp3', '', 1761754199, 1761754199),
(40661, 'Deuteronomy 13:16', 'Deuteronomy', 13, 16, 'د هغه ځای د اوسېدونکو ټول مال او جایداد راوړئ او د ښار په چوک کې یې انبار کړئ. بیا هغه ښار د هرڅه سره چې په کې دي خپل څښتن خدای ته د نذرانې په توګه وسوځوئ. هغه باید د تل دپاره کنډواله پاتې شي او بیا هېڅکله ودان نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy13_verse_16.mp3', '', 1761754199, 1761754199),
(40662, 'Jeremiah 31:1', 'Jeremiah', 31, 1, 'مالِک خُدائ فرمائى چې، ”په هغه وخت کښې به زۀ د بنى اِسرائيلو د ټولو قبيلو خُدائ يم، او هغوئ به زما خلق وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_1.mp3', '', 1761754199, 1761754199),
(40663, 'Jeremiah 31:2', 'Jeremiah', 31, 2, 'مالِک خُدائ داسې فرمائى چې، ”د بنى اِسرائيلو کوم خلق چې د مرګ نه بچ پاتې شوى وُو ما په هغوئ په بيابان کښې فضل وکړو، کله چې هغوئ د آرام په تلاش کښې روان وُو ما د هغوئ ساتنه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_2.mp3', '', 1761754199, 1761754199),
(40664, 'Jeremiah 31:3', 'Jeremiah', 31, 3, 'ډېر پخوا مالِک خُدائ بنى اِسرائيلو ته راڅرګند شو، او ورته يې وفرمائيل چې، ما تاسو سره نۀ ختمېدونکې مينه کړې ده، ما تاسو په خپله مينه او رحم سره خپل ځان ته رانزدې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_3.mp3', '', 1761754199, 1761754199),
(40665, 'Jeremiah 31:4', 'Jeremiah', 31, 4, 'زۀ به تا بيا آباد کړم، او تۀ به بيا آباد شې، اے پېغلې اِسرائيله. تۀ به بيا تمبل راواخلې او بهر به د ګډا دپاره په خوشحالۍ سره راووځې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_4.mp3', '', 1761754199, 1761754199),
(40666, 'Jeremiah 31:5', 'Jeremiah', 31, 5, 'تاسو به دوباره د سامريه په غونډو باندې د انګورو باغونه وکَرئ، او څوک چې دا باغونه کَرى هغوئ به يې په مېوه خوشحاله شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_5.mp3', '', 1761754199, 1761754199),
(40667, 'Jeremiah 31:6', 'Jeremiah', 31, 6, 'نو هغه ورځ راروانه ده چې د اِفرائيم د غونډو نه به چوکيداران آوازونه وکړى او وائى به چې، راځئ چې صيون ته د عبادت دپاره او مالِک خُدائ خپل خُدائ پاک ته لاړ شو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_6.mp3', '', 1761754199, 1761754199),
(40668, 'Jeremiah 31:7', 'Jeremiah', 31, 7, 'مالِک خُدائ فرمائى چې، ”د يعقوب دپاره د خوشحالۍ سندرې ووايئ او چغې ووهئ چې بنى اِسرائيل د ټولو نه لوئ قوم دے. مالِک خُدائ ته د حمد و ثناء چغې ووهئ او ووايئ چې، اے مالِکه خُدايه، په بنى اِسرائيلو کښې پاتې شوے خپل قوم دې بچ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_7.mp3', '', 1761754199, 1761754199),
(40669, 'Jeremiah 31:8', 'Jeremiah', 31, 8, 'نو زۀ به هغوئ د شمالى مُلک نه واپس راولم او د زمکې د لرو ځايونو نه به يې راغونډ کړم. تر دې چې ړاندۀ، ګوډيان، اُميدوارې ښځې او د ماشوم د پېدا کېدو په حالت کښې ښځې، نو هغوئ ټول به د لوئ قبيلې په شکل کښې دلته بيا راواپس شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_8.mp3', '', 1761754199, 1761754199),
(40670, 'Jeremiah 31:9', 'Jeremiah', 31, 9, 'کله چې هغوئ واپس راشى نو د پښېمانۍ نه به اوښکې د هغوئ په مخ روانې وى او زۀ به هغوئ په ډېره مينه خپلو کورونو ته واپس بوځم، نو زۀ به هغوئ د روانو اوبو په خوا کښې او په هواره لاره بوځم هسې نه چې چرته تيندک وخورى، ځکه چې زۀ د بنى اِسرائيلو پلار يم، او اِفرائيم زما مشر زوئ دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_9.mp3', '', 1761754199, 1761754199),
(40671, 'Jeremiah 31:10', 'Jeremiah', 31, 10, 'مالِک خُدائ فرمائى، ”اے قومونو، د مالِک خُدائ کلام واورئ، او هغه لرې ساحلى وطنونو ته يې بيان کړئ. هغه چا چې بنى اِسرائيل خوارۀ کړى دى هم هغه به يې راغونډ کړى. لکه څنګه چې شپونکے د خپلې رمې ساتنه کوى هم داسې به هغه د هغوئ خيال ساتى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_10.mp3', '', 1761754199, 1761754199),
(40672, 'Jeremiah 31:11', 'Jeremiah', 31, 11, 'مالِک خُدائ به د بنى اِسرائيلو فديه ورکړى او هغوئ به د هغه کسانو نه آزاد کړى چې د دوئ نه زورَور دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_11.mp3', '', 1761754199, 1761754199),
(40673, 'Jeremiah 31:12', 'Jeremiah', 31, 12, 'هغوئ به راشى او پاس د صيون په غرۀ به د خوشحالۍ چغې ووهى، او هغوئ به د مالِک خُدائ په برکتونو لکه غله دانه، مے، تېل، او د رمو په زياتولو خوشحاله شى. د هغوئ ژوند به لکه د سيرابه باغ په شان وى، او هغوئ به نور غمژن نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_12.mp3', '', 1761754199, 1761754199),
(40674, 'Jeremiah 31:13', 'Jeremiah', 31, 13, 'نو پېغلې به د خوشحالۍ نه ګډيږى، ځوانان او بوډاګان به هم خوشحالى کوى. زۀ به د هغوئ غم په خوشحالۍ باندې بدل کړم، او زۀ به هغوئ له تسلى ورکړم، او زۀ به د هغوئ خفګان په خوشحالۍ بدل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_13.mp3', '', 1761754199, 1761754199),
(40675, 'Jeremiah 31:14', 'Jeremiah', 31, 14, 'زۀ به د هغوئ اِمامان په غوړو زېړو خوراکونو ماړۀ کړم، او زما خلق به زما په نعمتونو باندې ماړۀ پټ شى. مالِک خُدائ دا فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_14.mp3', '', 1761754199, 1761754199),
(40676, 'Jeremiah 31:15', 'Jeremiah', 31, 15, 'مالِک خُدائ فرمائى چې، ”په راما کښې د چغو آواز واورېدلے شو، د ماتم او لوئ ژړا آواز. راحيل په خپلو بچو باندې ژړا کوى، هيڅ قسم تسلى نۀ قبلوى ځکه چې د هغې ماشومان غېب کړے شوى دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_15.mp3', '', 1761754199, 1761754199),
(40677, 'Jeremiah 31:16', 'Jeremiah', 31, 16, 'خو مالِک خُدائ فرمائى چې، ”ژړا او اوښکې توېدل بس کړئ، تاسو ته به د خپلو کارونو اجر مِلاو شى.“ مالِک خُدائ داسې فرمائى چې، ”ستاسو ماشومان به د دشمن د مُلک نه راواپس شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_16.mp3', '', 1761754199, 1761754199),
(40678, 'Jeremiah 31:17', 'Jeremiah', 31, 17, 'مالِک خُدائ داسې فرمائى چې، ”ستا د راتلونکى ژوند دپاره اُميد شته دے، ستاسو ماشومان به خپل مُلک ته بيا واپس راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_17.mp3', '', 1761754199, 1761754199),
(40679, 'Jeremiah 31:18', 'Jeremiah', 31, 18, 'د اِفرائيم ژړا او فرياد ما ته رارسېدلے دے، تا ما ته تربيت راکړو چې په لاره شم، لکه د ناجوته سخى په شان دې تربيت راکړو او زۀ اوس په لاره شوے يم. ما دې خپل حضور ته واپس راوله، نو زۀ به واپس راشم، ځکه چې تۀ زما مالِک خُدائ او خُدائ پاک يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_18.mp3', '', 1761754199, 1761754199),
(40680, 'Jeremiah 31:19', 'Jeremiah', 31, 19, 'ستا نه د اوړېدو نه پس مونږ توبه وکړه، د پوهېدو نه وروستو مونږ خپله سينه ووهله. مونږ چې کوم کم عقل کارونه په ځوانۍ کښې کړى وُو د هغې په وجه سپک او شرمنده شُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_19.mp3', '', 1761754199, 1761754199),
(40681, 'Jeremiah 31:20', 'Jeremiah', 31, 20, 'مالِک خُدائ فرمائى چې، ”ولې اِسرائيل تر اوسه زما محبوب زوئ نۀ دے څۀ په چا کښې چې زۀ خوشحالېږم؟ کۀ څۀ هم چې زۀ د دۀ خلاف بار بار خبرې کوم، نو بيا هم هغه يادوم. نو په دې وجه زما زړۀ ورپسې زهيريږى، زما په زړۀ کښې د دۀ دپاره ډېر رحم دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_20.mp3', '', 1761754199, 1761754199),
(40682, 'Jeremiah 31:21', 'Jeremiah', 31, 21, 'اے زما قومه، تاسو د تلو په وخت په خپله لار داسې نښې ودروئ چې د هغې نه په واپسۍ کښې خلقو ته د صحيح لارې پته ولګى. اے پېغلې اِسرائيله راوګرځه، خپلو ښارونو ته راوګرځه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_21.mp3', '', 1761754199, 1761754199),
(40683, 'Jeremiah 31:22', 'Jeremiah', 31, 22, 'اے زما بې‌وفا لورې، تۀ به ترڅو پورې سرګردانه ګرځې؟ مالِک خُدائ به يو نوے کار وکړى او هغه دا دے چې بنى اِسرائيل به خپل مالِک خُدائ ته غاړه ورکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_22.mp3', '', 1761754199, 1761754199),
(40684, 'Jeremiah 31:23', 'Jeremiah', 31, 23, 'مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ پاک فرمائى، ”کله چې زۀ هغوئ د غلامۍ نه واپس راولم، په يهوداه او د هغې په ښارونو کښې به هغوئ بيا داسې ووائى چې، اے د صداقت ځايه، اے مقدس غره، مالِک خُدائ دې تا له برکت درکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_23.mp3', '', 1761754199, 1761754199),
(40685, 'Jeremiah 31:24', 'Jeremiah', 31, 24, 'ښاريان او زمينداران او شپونکى به د خپلو رمو سره په شريکه د يهوداه په مُلک کښې اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_24.mp3', '', 1761754199, 1761754199),
(40686, 'Jeremiah 31:25', 'Jeremiah', 31, 25, 'زۀ به ستړو ستومانو ته طاقت ورکړم او مړاوى شوى به تازه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_25.mp3', '', 1761754199, 1761754199),
(40687, 'Jeremiah 31:26', 'Jeremiah', 31, 26, 'نو کله چې زۀ راپاڅېدم او خپلې سترګې مې پرانستلې، نو زۀ پوهه شوم چې په خوږ خوب اودۀ وم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_26.mp3', '', 1761754199, 1761754199),
(40688, 'Jeremiah 31:27', 'Jeremiah', 31, 27, 'مالِک خُدائ فرمائى چې، ”هغه ورځ راروانه ده چې زۀ به د اِسرائيل او يهوداه او د هغوئ د ځناورو نسلونه زيات کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_27.mp3', '', 1761754199, 1761754199),
(40689, 'Jeremiah 31:28', 'Jeremiah', 31, 28, 'او لکه څنګه چې ما هغوئ د بېخ نه راويستل، او ټوکړې ټوکړې مې کړل، او راومې غورزول، او تباه مې کړل او افتونه مې پرې نازل کړل، نو دغه شان به زۀ هغوئ دوباره آباد او قائم کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_28.mp3', '', 1761754199, 1761754199),
(40690, 'Jeremiah 31:29', 'Jeremiah', 31, 29, 'په هغه ورځو کښې به نور خلق داسې نۀ وائى چې، تراوۀ انګور يې پلارانو وخوړل، او غاښونه يې د بچو وبرېښېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_29.mp3', '', 1761754199, 1761754199),
(40691, 'Jeremiah 31:30', 'Jeremiah', 31, 30, 'خو هر سړے به د خپلې ګناه په وجه مړ کيږى، هر څوک چې تراوۀ انګور وخورى هم د هغۀ غاښونه به برېښيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_30.mp3', '', 1761754199, 1761754199),
(40692, 'Jeremiah 31:31', 'Jeremiah', 31, 31, 'مالِک خُدائ فرمائى چې، ”هغه وخت راروان دے چې کله زۀ د اِسرائيل او د يهوداه د خلقو سره يو نوے لوظ وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_31.mp3', '', 1761754199, 1761754199),
(40693, 'Jeremiah 31:32', 'Jeremiah', 31, 32, 'دا به د هغه لوظ په شان نۀ وى کوم چې ما د هغوئ د پلار نيکۀ سره کړے وو کله چې ما هغوئ د لاس نه ونيول او د مِصر نه مې بهر وويستل، ځکه چې هغوئ ما سره کړے لوظ مات کړو، کۀ څۀ هم چې زما مثال هغوئ ته د وفادار خاوند په شان وو. مالِک خُدائ داسې فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_32.mp3', '', 1761754199, 1761754199),
(40694, 'Jeremiah 31:33', 'Jeremiah', 31, 33, 'خو دا هغه نوے لوظ دے کوم به چې زۀ پس د دې نه د بنى اِسرائيلو د قبيلې سره وکړم، زۀ به خپل شريعت د هغوئ په مازغو کښې واچوم او د هغوئ په زړونو به يې وليکم. زۀ به د هغوئ خُدائ پاک يم او هغوئ به زما بنده ګان وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_33.mp3', '', 1761754199, 1761754199),
(40695, 'Jeremiah 31:34', 'Jeremiah', 31, 34, 'نور به د هغوئ نه يو کس هم خپل ګاونډى ته، او يا خپل ورور ته دا تعليم نۀ ورکوى چې مالِک خُدائ وپېژنه، ځکه چې د وړو نه واخله تر لويو پورې به هغوئ ټول ما پېژنى، مالِک خُدائ داسې فرمائى. زۀ به د هغوئ شرارتونه معاف کړم او د هغوئ ګناهونه به نور نۀ يادوم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_34.mp3', '', 1761754199, 1761754199),
(40696, 'Jeremiah 31:35', 'Jeremiah', 31, 35, 'مالِک خُدائ داسې فرمائى، هغه څوک چې نمر په دې مقرروى چې د ورځې وځليږى، او هغه چا چې سپوږمۍ او ستورى مقرر کړل چې د شپې وځليږى، څوک چې سمندر راپاڅوى چې د هغې چپې شور وکړى نو د هغۀ نوم مالِک خُدائ ربُ الافواج دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_35.mp3', '', 1761754199, 1761754199),
(40697, 'Jeremiah 31:36', 'Jeremiah', 31, 36, 'مالِک خُدائ داسې فرمائى چې، ”ترڅو پورې د کائنات دا نظام موجود وى، نو تر هغه وخته پورې به د بنى اِسرائيلو قوم زما د وړاندې قائم وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_36.mp3', '', 1761754199, 1761754199),
(40698, 'Jeremiah 31:37', 'Jeremiah', 31, 37, 'مالِک خُدائ داسې فرمائى چې، ”لکه څنګه چې د آسمان د ناپ تول اندازه نۀ شى لګولے او د زمکې د بنياد اندازه نۀ شى معلومولے نو زۀ به هم د اِسرائيل د ګناهونو په وجه د هغوئ نه اِنکار ونۀ کړم.“ دا د مالِک خُدائ فرمان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_37.mp3', '', 1761754199, 1761754199),
(40699, 'Jeremiah 31:38', 'Jeremiah', 31, 38, '”هغه ورځ راتلونکى ده،“ مالِک خُدائ فرمائى چې، ”کله چې دا ښار د حنن‌ايل د برج نه واخله تر د ګوټ د دروازې پورې به دوباره زما دپاره آباد شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_38.mp3', '', 1761754199, 1761754199),
(40700, 'Jeremiah 31:39', 'Jeremiah', 31, 39, 'او د هغه ځائ نه به سيدها د ښار حدود جارب غونډۍ پورې ورسيږى او بيا به د جوعه طرف ته راتاو شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_39.mp3', '', 1761754199, 1761754199),
(40701, 'Jeremiah 31:40', 'Jeremiah', 31, 40, 'نو بيا به ټوله دره چرته چې د مړو لاشونه او ايرې غورزولے شى او هغه ټوله زمکه د کومې مېدانونه چې د قِدرون د درې د نمرخاتۀ پورې پراتۀ دى، او د آسونو د دروازې پورې، ټوله به مالِک خُدائ ته مقدسه وى. دا ښار به هيڅکله بيا د بېخ نه راونۀ ويستلے شى او نۀ به تباه شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah31_verse_40.mp3', '', 1761754199, 1761754199),
(40702, 'Daniel 5:1', 'Daniel', 5, 1, 'يوه ورځ بيلشضر بادشاه يوه لويه مېلمستيا تياره کړه او د خپلو آفسرانو نه يې زر کسان راوغوښتل او د هغوئ سره يې يوځائ مے وڅښل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_1.mp3', '', 1761754199, 1761754199),
(40703, 'Daniel 5:2', 'Daniel', 5, 2, 'کله چې بيلشضر خپل مے څښل، نو هغۀ حکم وکړو چې هغه د سرو زرو او سپينو زرو جامونه او پيالۍ راوړئ کومې چې د هغۀ پلار نبوکدنضر په يروشلم کښې د مالِک خُدائ د کور نه راوړې وې، چې بادشاه او د هغۀ آفسران، د هغۀ ښځې او د هغۀ وينځې په کښې مے وڅښى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_2.mp3', '', 1761754199, 1761754199),
(40704, 'Daniel 5:3', 'Daniel', 5, 3, 'نو بيا هغوئ د سرو زرو جامونه او پيالۍ راوړې کومې چې په يروشلم کښې د خُدائ پاک د کور نه راوړلے شوې وې، او بادشاه او د هغۀ آفسرانو، د هغۀ ښځو او د هغۀ وينځو په هغو کښې وڅښل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_3.mp3', '', 1761754199, 1761754199),
(40705, 'Daniel 5:4', 'Daniel', 5, 4, 'کله چې هغوئ مے څښل، نو بيا هغوئ د سرو زرو، سپينو زرو، پيتلو، اوسپنو، د لرګى او د کاڼو نه د جوړو شوو معبودانو ثناء صِفت وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_4.mp3', '', 1761754199, 1761754199),
(40706, 'Daniel 5:5', 'Daniel', 5, 5, 'او ناګهانه د انسان د لاس ګوتې راښکاره شوې او د شاهى محل د دېوال په پلستر باندې د شمعدان سره نزدې ليکل وکړل. کله چې هغه لاس ليکل کول نو بادشاه په خپله هغه وليدلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_5.mp3', '', 1761754199, 1761754199),
(40707, 'Daniel 5:6', 'Daniel', 5, 6, 'د هغۀ رنګ د يرې نه تک زېړ شو او دومره يرېدلے وو چې د پښو د رپېدو په وجه په ځائ ودرېدلے نۀ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_6.mp3', '', 1761754199, 1761754199),
(40708, 'Daniel 5:7', 'Daniel', 5, 7, 'نو بادشاه په تېزه آواز وکړو چې جادوګر، فالګر او نجوميان راوغواړئ. نو د بابل دې هوښيارو سړو ته بادشاه ووئيل چې، ”هر څوک چې دا ليکلے شوى الفاظ ولولى او د هغې مطلب راته بيان کړى نو هغۀ ته به کاسنى چُوغه د عزت دپاره ورواغوستلے شى او د هغۀ په غاړه کښې به د سرو زرو هار واچولے شى، او په بادشاهۍ کښې به ورته درېم مقام مِلاو شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_7.mp3', '', 1761754199, 1761754199),
(40709, 'Daniel 5:8', 'Daniel', 5, 8, 'نو بيا د بادشاه ټول هوښياران راغلل، خو هغوئ هغه ليکل ونۀ شُو لوستلے او نۀ يې بادشاه ته دا وئيلے شُو چې د دې څۀ مطلب دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_8.mp3', '', 1761754199, 1761754199),
(40710, 'Daniel 5:9', 'Daniel', 5, 9, 'نو بيا بيلشضر بادشاه نور هم يرې واخستو او د هغۀ رنګ نور هم زېړ شو. او د هغۀ ټول آفسران هم پرېشانه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_9.mp3', '', 1761754199, 1761754199);